def def_source_receipt(name):
    record=EMBEDDED_SOURCE_RECEIPTS.get(name)
    if record is None:raise KeyError('Unknown evidence receipt')
    data=_via_zlib.decompress(_via_b64.b85decode(record['b85']))
    if hashlib.sha256(data).hexdigest()!=record['sha256']:
        raise RuntimeError('Source SHA-256 mismatch; evidence damaged')
    return data


import base64 as _via_b64
import zlib as _via_zlib
from functools import lru_cache
from collections import Counter
import shutil as _via_shutil
import platform as _via_platform

@lru_cache(maxsize=1)
def def_baseline_html():
    """Preserve the exact v0105 browser report as read-only historical evidence."""
    return _via_zlib.decompress(_via_b64.b85decode(''.join(BASELINE_HTML_COMPRESSED_B85)))

@lru_cache(maxsize=1)
def def_baseline_model():
    source=def_baseline_html()
    prefix=b'<script id="model" type="application/json">'
    raw=source.split(prefix,1)[1].split(b'</script>',1)[0]
    return json.loads(raw)

def def_derived_matrix(matrix,offset=0,limit=40,search='',system='',status='',live_report=None):
    """Source-bound M1–M10 governance projections; no invented change/AI records."""
    key=matrix.lower()
    lookup={'m1':'systems','m2':'requirements','m3':'io','m4':'conflicts',
            'm5':'conflicts','m10':'conflicts'}
    if key in lookup:
        source=def_baseline_query(lookup[key],offset,limit,search,system,status)
        name=CONTROL_MATRIX_TITLES[key]
        if key in ('m1','m2','m3','m4'):
            source['matrix']=key;source['projection']=name
            return source
        mapping={
            'm5':['id','system','status','detail','error_detail','solution','temporary_fix','permanent_fix','owner','retest_result','approval','source'],
            'm10':['id','system','status','detail','error_detail','severity','risk_level','approval','evidence','source'],
        }[key]
        out=[]
        for record in source['rows']:
            r=record['raw']
            values={k:(r[k] if k in r else 'NOT_OBSERVED') for k in mapping}
            out.append({'id':r.get('id'),'display':values,'raw':dict(r,projection_status='SOURCE_BOUND_UNVERIFIED')})
        source.update(matrix=key,projection=name,columns=mapping,rows=out,
                      source='Static incidents only; solution/approval absent => NOT_OBSERVED')
        return source
    if key=='m9':
        records=[]
        for item in adapter_status():
            # Each third-party name is a catalogued adapter, NOT executed integration.
            records.append({'name':item.get('name'),'role':item.get('role'),'status':item.get('status'),
                           'source':'LOCAL_CAPABILITY_CATALOG','runtime_integration':'NOT_EXECUTED'})
        if search:records=[r for r in records if search.lower() in json.dumps(r).lower()]
        chunk=records[max(0,offset):max(0,offset)+max(1,min(limit,BASELINE_MATRIX_LIMIT))]
        columns=['name','role','status','runtime_integration','source']
        return {'matrix':key,'offset':offset,'limit':limit,'total':len(records),
                'columns':columns,'rows':[{'id':r['name'],'display':r,'raw':r} for r in chunk],
                'source':'Adapter catalog; NOT an evidence of live vendor integration'}
    if key=='m7':
        records=[]
        if live_report and live_report.get('cases'):
            for row in live_report.get('state_matrix',[]):
                records.append({'stage':row.get('stage'),'latency_ms':row.get('elapsed_ms'),
                                'test_pass_rate':row.get('pass_rate'),'scope':'LOCAL_FIXTURE_ONLY',
                                'status':row.get('status'),'tps':(live_report.get('stress') or {}).get('tps')})
        columns=['stage','latency_ms','test_pass_rate','tps','status','scope']
        return {'matrix':key,'offset':offset,'limit':limit,'total':len(records),
                'columns':columns,'rows':[{'id':r['stage'],'display':r,'raw':r} for r in records],
                'source':'Local measured execution only, not enterprise production capacity'}
    if key in ('m6','m8'):
        columns=(['change_id','version_before','version_after','approval','rollback_plan','status']
                 if key=='m6' else
                 ['agent','model','prompt_version','rag_source','token_cost','hallucination_score','human_review','status'])
        return {'matrix':key,'offset':0,'limit':limit,'total':0,'columns':columns,'rows':[],
                'source':'NOT_OBSERVED; missing source records are never auto-generated'}
    raise ValueError('Unknown control matrix')

def def_baseline_query(matrix='io',offset=0,limit=40,search='',system='',status=''):
    """Bounded server-side pagination, never transfer 30k rows to the browser at once."""
    if matrix in CONTROL_MATRIX_TITLES:return def_derived_matrix(matrix,offset,limit,search,system,status)
    matrices=def_baseline_model().get('matrices',{})
    if matrix not in matrices:raise ValueError('Unknown matrix')
    records=matrices[matrix]
    if not isinstance(records,list):raise ValueError('Not a matrix collection')
    limit=max(1,min(BASELINE_MATRIX_LIMIT,int(limit)))
    offset=max(0,int(offset))
    search=str(search).strip().lower()[:100]
    system=str(system).strip().upper()[:70]
    status=str(status).strip().upper()[:20]
    def matches(r):
        if system and system not in str(r.get('system','')).upper():return False
        if status and status!=str(r.get('status','')).upper():return False
        if search:
            terms=(r.get('ssot_name'),r.get('id'),r.get('system'),r.get('source'),r.get('kind'),r.get('qualname'),r.get('key'),r.get('name'),r.get('input'),r.get('output'))
            return any(search in str(x or '').lower() for x in terms)
        return True
    matching=[r for r in records if matches(r)]
    sample=matching[offset:offset+limit]
    preferred=['status','id','ssot_name','system','process','module','class','function','source','direction','input','output','type','default','regex','synonyms','evidence','error_detail','version','unit_test','integration_test','system_test','output_verification']
    others=[]
    for r in sample[:12]:
        for k in r:
            if k not in preferred and k not in others:others.append(k)
    columns=[k for k in preferred if any(k in r for r in sample)]+others[:12]
    columns=columns[:20]
    rows=[]
    for r in sample:
        brief={k:r.get(k) for k in columns}
        rows.append({'display':brief,'id':r.get('id'),'raw':r})
    return {'matrix':matrix,'offset':offset,'limit':limit,'total':len(matching),'columns':columns,'rows':rows,
            'source':'v0105 immutable snapshot; source-evidence status is not real-time execution'}

def def_script_json(value):
    # Escape untrusted snapshot strings before embedding inside an inline <script>.
    return canonical_json(value).replace('&','\\u0026').replace('<','\\u003c').replace('>','\\u003e').replace('\u2028','\\u2028').replace('\u2029','\\u2029')

def def_console_summary():
    snapshot=def_baseline_model()
    counts={k:len(v) for k,v in snapshot.get('matrices',{}).items()}
    return {'engine_version':VERSION,'snapshot_version':snapshot.get('version'),
            'matrices':counts,'counts':snapshot.get('counts',{}),
            'snapshot_meta':snapshot.get('meta',{}),
            'production_go_live':False,'source_receipts':[{ 'name':k,'sha256':v['sha256'],'source':v['original_name']} for k,v in EMBEDDED_SOURCE_RECEIPTS.items()],
            'note':'歷史靜態盤點，正式環境尚未連線、未經 VCGC 發號'}

def def_visual_probe_script():
    """Browser-side DOM measurements with bounded samples and false-positive reduction."""
    return r'''() => {
      const all=[...document.querySelectorAll('body *')];
      const visible=e=>{const x=e.getBoundingClientRect(),s=getComputedStyle(e);return x.width>2&&x.height>2&&s.display!=='none'&&s.visibility!=='hidden'};
      const badOverflow=[];const smallFonts=[];
      for(const e of all){if(!visible(e))continue;
        const sw=e.scrollWidth,cw=e.clientWidth;
        const style=getComputedStyle(e);
        if(sw>cw+5 && style.overflowX==='visible' && e.tagName!=='svg' && !e.closest('.table-scroller'))badOverflow.push({tag:e.tagName,cls:String(e.className).slice(0,75),pixels:sw-cw});
        if(e.children.length===0 && e.textContent.trim() && parseFloat(style.fontSize)<11)smallFonts.push({tag:e.tagName,text:e.textContent.trim().slice(0,40),px:parseFloat(style.fontSize)});
      }
      const tables=[...document.querySelectorAll('table')].map(e=>({rows:e.rows.length,cols:e.rows[0]?.cells.length||0,
            scroll:e.scrollWidth,client:e.clientWidth,stickyHeader:getComputedStyle(e.querySelector('th')||e).position==='sticky'}));
      const rects=[...document.querySelectorAll('.metric-card,.panel,.nav-item,.toolbar button')].filter(visible).slice(0,120).map(e=>({el:e,r:e.getBoundingClientRect()}));
      const overlaps=[];
      for(let i=0;i<rects.length;i++){for(let j=i+1;j<rects.length;j++){
        const a=rects[i],b=rects[j];if(a.el.contains(b.el)||b.el.contains(a.el))continue;
        const x=Math.min(a.r.right,b.r.right)-Math.max(a.r.left,b.r.left),y=Math.min(a.r.bottom,b.r.bottom)-Math.max(a.r.top,b.r.top);
        if(x>8&&y>8&&x*y/Math.min(a.r.width*a.r.height,b.r.width*b.r.height)>.13)overlaps.push({a:a.el.className,b:b.el.className,ratio:Math.round(x*y/Math.min(a.r.width*a.r.height,b.r.width*b.r.height)*100)/100});
      }}
      return {overflow:badOverflow.slice(0,60),tinyFont:smallFonts.slice(0,40),overlaps:overlaps.slice(0,40),tables,
        documentWidth:document.documentElement.scrollWidth,viewportWidth:innerWidth,
        pageOverflow:document.documentElement.scrollWidth>innerWidth+5};
    }'''

def def_browser_visual_audit(url:str,destination:Path,baseline_dir:Path|None=None)->dict:
    """12 genuine browser renders. Browser not installed => explicit BLOCKED, never fake PASS."""
    destination=Path(destination).resolve()
    destination.mkdir(parents=True,exist_ok=True)
    report={'time':utcnow(),'url':url,'status':'RUNNING','cases':[],'screenshots':[],
            'lighthouse':{'status':'NOT_EXECUTED','reason':'needs explicit local CLI installation and opt-in'},
            'visual_regression':{'status':'NOT_EXECUTED','reason':'reference screenshots not provided'},
            'execution_scope':'Playwright Chromium, local HTTP, no GitHub writes'}
    try:
        from playwright.sync_api import sync_playwright
        with sync_playwright() as p:
            launch={ 'headless':True }
            # Some Linux images ship a system Chromium rather than Playwright managed binaries.
            if _via_shutil.which('chromium') and not (Path.home()/'.cache'/'ms-playwright').exists():
                launch['executable_path']=_via_shutil.which('chromium')
                launch['args']=['--no-sandbox']
            try:
                browser=p.chromium.launch(**launch)
            except Exception:
                chrome=_via_shutil.which('chromium') or _via_shutil.which('google-chrome')
                if not chrome:raise
                browser=p.chromium.launch(headless=True,executable_path=chrome,args=['--no-sandbox'])
            try:
                probe=browser.new_page()
                try:
                    probe.goto(url,wait_until='domcontentloaded',timeout=VISUAL_NAV_TIMEOUT_MS)
                    report['render_mode']='LIVE_HTTP'
                except Exception as probe_error:
                    if 'ERR_BLOCKED_BY_ADMINISTRATOR' not in str(probe_error):
                        raise
                    report['render_mode']='OFFLINE_TEMPLATE_ONLY'
                    report['limitation']='Browser administrator blocked loopback; static HTML render only. API/WS interactions require separate verification.'
                finally:probe.close()
                for name,width,height in VISUAL_VIEWPORTS:
                    for density in VISUAL_DENSITIES:
                        context=browser.new_context(viewport={'width':width,'height':height},device_scale_factor=1,
                                                   reduced_motion='reduce')
                        page=context.new_page()
                        errors=[]
                        page.on('pageerror',lambda err: errors.append(str(err)))
                        try:
                            if report.get('render_mode')=='OFFLINE_TEMPLATE_ONLY':
                                template=CONSOLE_HTML.replace('__SESSION_TOKEN__',json.dumps('OFFLINE_TEST')).replace('__UI_VERSION__',VERSION)
                                template=template.replace('__OFFLINE_IO__',def_script_json(def_baseline_query('io',limit=20))).replace('__OFFLINE_SUMMARY__',def_script_json(def_console_summary()))
                                page.set_content(template,wait_until='domcontentloaded')
                            else:
                                page.goto(url,wait_until='domcontentloaded',timeout=VISUAL_NAV_TIMEOUT_MS)
                            page.evaluate('(mode)=>document.body.dataset.density=mode',density)
                            page.wait_for_timeout(200)
                            findings=page.evaluate(def_visual_probe_script())
                            shot=f'{name}-{density}.png'
                            page.screenshot(path=str(destination/shot),full_page=False,animations='disabled')
                            report['screenshots'].append(shot)
                            failed=bool(errors or findings['pageOverflow'] or findings['overlaps'])
                            report['cases'].append({'viewport':name,'width':width,'height':height,'density':density,
                                'status':'FAIL' if failed else 'PASS','findings':findings,'js_errors':errors})
                        except Exception as ex:
                            report['cases'].append({'viewport':name,'density':density,'status':'ERROR','error':str(ex)})
                        finally:
                            context.close()
            finally:
                browser.close()
        report['status']=('PASS' if report.get('render_mode')=='LIVE_HTTP' else 'PASS_LAYOUT_ONLY') if len(report['cases'])==len(VISUAL_VIEWPORTS)*len(VISUAL_DENSITIES) and all(c['status']=='PASS' for c in report['cases']) else 'FAIL'
        if baseline_dir is not None:report['visual_regression']=def_visual_regression(destination,baseline_dir)
    except Exception as ex:
        report['status']='BLOCKED'
        report['reason']=str(ex)
    with (destination/'visual-report.json').open('w',encoding='utf-8') as f:
        json.dump(report,f,ensure_ascii=False,indent=2)
    return report

def def_visual_regression(destination:Path,baseline_dir:Path):
    """Optional real screenshot comparison against an explicitly supplied trusted baseline."""
    baseline_dir=Path(baseline_dir).resolve()
    result={'status':'NOT_EXECUTED','baseline_dir':str(baseline_dir),'cases':[]}
    if not baseline_dir.is_dir():
        result['reason']='baseline folder not found'
        return result
    try:
        from PIL import Image,ImageChops
    except ImportError:
        result.update(status='BLOCKED',reason='Pillow is required for Pixel Diff')
        return result
    for candidate in sorted(Path(destination).glob('*.png')):
        original=baseline_dir/candidate.name
        if not original.is_file():
            result['cases'].append({'name':candidate.name,'status':'NO_BASELINE'})
            continue
        try:
            with Image.open(original) as a,Image.open(candidate) as b:
                a=a.convert('RGB');b=b.convert('RGB')
                if a.size!=b.size:
                    result['cases'].append({'name':candidate.name,'status':'SIZE_MISMATCH',
                                            'before':a.size,'after':b.size});continue
                # A measured changed-pixel fraction, not a claim of visual equivalence.
                diff=ImageChops.difference(a,b)
                changed=sum(1 for pixel in diff.getdata() if max(pixel)>25)
                ratio=changed/(a.width*a.height)
                result['cases'].append({'name':candidate.name,'changed_pixel_ratio':round(ratio,6),
                    'status':'PASS' if ratio<=VISUAL_PIXEL_DIFF_TOLERANCE else 'FAIL'})
        except Exception as exc:
            result['cases'].append({'name':candidate.name,'status':'ERROR','error':str(exc)})
    checked=[c for c in result['cases'] if c['status'] in ('PASS','FAIL','SIZE_MISMATCH','ERROR')]
    result['status']='NOT_EXECUTED' if not checked else ('PASS' if all(c['status']=='PASS' for c in checked) else 'FAIL')
    if not checked:result['reason']='No matching screenshot baselines'
    return result

def def_lighthouse_audit(local_url:str,destination:Path):
    """Explicit local-only CLI. No npx downloads, no GitHub upload, no public URL."""
    import subprocess
    from urllib.parse import urlsplit
    parts=urlsplit(local_url)
    if parts.hostname not in ('127.0.0.1','localhost') or parts.scheme!='http':
        raise ValueError('Lighthouse only accepts locally hosted VIA pages')
    executable=_via_shutil.which('lighthouse')
    if executable is None:
        return {'status':'BLOCKED','reason':'Install Lighthouse CLI locally first; npx not invoked'}
    destination=Path(destination);destination.mkdir(parents=True,exist_ok=True)
    path=destination/'lighthouse.json'
    command=[executable,local_url,'--chrome-flags=--headless --no-sandbox','--output=json',
             '--output-path='+str(path),'--quiet']
    try:
        completed=subprocess.run(command,capture_output=True,text=True,timeout=LIGHTHOUSE_TIMEOUT_SEC,check=False)
        if completed.returncode!=0:return {'status':'FAIL','error':completed.stderr[-2500:]}
        payload=json.loads(path.read_text('utf8'))
        scores={k:round(100*v.get('score',0)) for k,v in payload.get('categories',{}).items()}
        evaluated={k:scores.get(k,0)>=limit for k,limit in LIGHTHOUSE_THRESHOLDS.items()}
        return {'status':'PASS' if all(evaluated.values()) else 'FAIL','scores':scores,
                'thresholds':LIGHTHOUSE_THRESHOLDS,'gates':evaluated,'path':str(path)}
    except Exception as ex:
        return {'status':'ERROR','error':str(ex)}

def def_emit_ci(destination:Path):
    """Opt-in export. Generates CI YAML, never automatically uploads/pushes."""
    destination=Path(destination)
    destination.parent.mkdir(parents=True,exist_ok=True)
    yml='''name: VIA Matrix and Visual QA (read-only)
on:
  workflow_dispatch:
  pull_request:
permissions:
  contents: read
jobs:
  verify:
    runs-on: ubuntu-latest
    timeout-minutes: 30
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: '3.12'
      - name: Dependencies
        run: |
          python -m pip install fastapi 'uvicorn[standard]' pyarrow psutil playwright
          python -m playwright install --with-deps chromium
      - name: Python and governance smoke
        run: |
          python VIA_SystemIntegrationEngine.py --self-test
          python VIA_SystemIntegrationEngine.py --smoke --data-dir ./artifacts
      - name: Visual QA across four viewports and three densities
        run: |
          python VIA_SystemIntegrationEngine.py --visual-test --data-dir ./artifacts
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: via-qa-evidence
          path: artifacts/
'''
    destination.write_text(yml,encoding='utf-8')
    return str(destination)

# Preserve old FastAPI engine and attach new matrices+governance endpoints.
_PREVIOUS_CREATE_APP=create_app

def create_app(vault:AuditVault,network_allowed:bool=False):
    from fastapi.routing import APIRoute
    from fastapi import Query
    from fastapi.responses import Response, FileResponse
    app=_PREVIOUS_CREATE_APP(vault,network_allowed)
    token=app.state.local_token
    governance_root=vault.root/GOVERNANCE_OUTPUT_SUBDIR
    visual_root=vault.root/VISUAL_OUTPUT_SUBDIR
    state={'lock':threading.RLock(),'running':False,'report':None,'cancel':None,'error':None,
           'visual_running':False,'visual_report':None,'visual_error':None}
    app.state.console_state=state
    def def_authorize(request:Request,provided:str|None):
        if not provided or not secrets.compare_digest(provided,token):
            raise HTTPException(status_code=403,detail='Invalid local session token')
        origin=request.headers.get('origin')
        if origin and origin not in app.state.allowed_origins:
            raise HTTPException(status_code=403,detail='Cross-origin request denied')
    def def_snapshot():
        with state['lock']:
            value=copy.deepcopy(state['report'])
            return {'running':state['running'],'report':value,'error':state['error'],
                    'visual_running':state['visual_running'],'visual_report':copy.deepcopy(state['visual_report']),
                    'visual_error':state['visual_error']}
    # Keep legacy visual DAG unchanged and available under a separate tab.
    async def def_console_root():
        return HTMLResponse(CONSOLE_HTML.replace('__SESSION_TOKEN__',json.dumps(token)).replace('__UI_VERSION__',VERSION).replace('__OFFLINE_IO__',def_script_json(def_baseline_query('io',limit=20))).replace('__OFFLINE_SUMMARY__',def_script_json(def_console_summary())),
            headers={'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','X-Frame-Options':'SAMEORIGIN',
             'Content-Security-Policy':"default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self' ws: wss:; img-src 'self' data: blob:; frame-src 'self'; object-src 'none'; base-uri 'none'"})
    app.router.routes.insert(0,APIRoute(path='/',endpoint=def_console_root,methods=['GET'],response_class=HTMLResponse))
    @app.get('/workspace/dag',response_class=HTMLResponse)
    async def def_workflow_page():
        htmlstr=HTML_TEMPLATE.replace('__VERSION__',VERSION).replace('__TOKEN_JSON__',json.dumps(token))
        htmlstr=htmlstr.replace('__INITIAL_JSON__',canonical_json(default_graph())).replace('__SPECS_JSON__',canonical_json(NODE_SPECS))
        return HTMLResponse(htmlstr,headers={'Content-Security-Policy':"default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self' ws: wss:; object-src 'none'; base-uri 'none'"})
    @app.get('/workspace/v0105',response_class=HTMLResponse)
    async def def_baseline_page():
        return Response(content=def_baseline_html(),media_type='text/html; charset=utf-8',headers={'Cache-Control':'no-store'})
    @app.get('/api/console/summary')
    async def def_summary(request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        return await asyncio.to_thread(def_console_summary)
    @app.get('/api/console/matrix')
    async def def_matrix(request:Request,matrix:str='io',offset:int=0,limit:int=40,q:str='',system:str='',status:str='',x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        try:
            if matrix=='m7':
                with state['lock']:latest=copy.deepcopy(state['report'])
                return def_derived_matrix(matrix,offset,limit,q,system,status,latest)
            return await asyncio.to_thread(def_baseline_query,matrix,offset,limit,q,system,status)
        except (ValueError,TypeError) as ex:raise HTTPException(status_code=400,detail=str(ex)) from ex
    @app.get('/api/console/runtime')
    async def def_runtime(request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        return {'python':sys.version.split()[0],'platform':_via_platform.platform(),
                'engine':VERSION,'go_live':False,'source':'local runtime (not user Windows environment)',
                'pyarrow':bool(importlib.util.find_spec('pyarrow')),
                'playwright':bool(importlib.util.find_spec('playwright')),
                'duckdb':_duckdb is not None,'polars':_pl is not None,
                'network_external_enabled':network_allowed,
                'production_gates':[{'id':a,'label':b,'status':'NOT_EXECUTED'} for a,b in PRODUCTION_REQUIREMENTS]}
    @app.get('/api/console/state')
    async def def_state(request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        return def_snapshot()
    @app.post('/api/console/check-input')
    async def def_check_input(request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        body=await request.json(); rows=body.get('rows')
        if not isinstance(rows,list) or len(rows)>MAX_ROWS:raise HTTPException(status_code=400,detail='Expected rows array')
        valid,rejected,duplicates=await asyncio.to_thread(prepare_rows,rows)
        return {'valid_count':len(valid),'duplicates':duplicates,'rejected':rejected[:100],
                'sample':valid[:15],'policy':POLICY,'status':'PASS' if not rejected and valid else 'BLOCKED'}
    @app.post('/api/console/matrix-run')
    async def def_matrix_run(request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        body=await request.json();rows=body.get('rows',SAMPLE_ROWS);resume=body.get('resume',False)
        if not isinstance(rows,list) or not 0<len(rows)<=MAX_ROWS or not isinstance(resume,bool):
            raise HTTPException(status_code=400,detail='Invalid rows/resume')
        with state['lock']:
            if state['running']:raise HTTPException(status_code=409,detail='Governance run already active')
            state['running']=True;state['error']=None;state['cancel']=threading.Event()
            state['report']=new_report('starting')
        def def_update(report):
            with state['lock']:state['report']=report
        def def_governance_worker():
            try:
                run_pipeline(rows,governance_root,cancel=state['cancel'],on_update=def_update,resume=resume)
            except Exception as ex:
                with state['lock']:state['error']=f'{type(ex).__name__}: {ex}'
            finally:
                with state['lock']:state['running']=False
        threading.Thread(target=def_governance_worker,name='VIA-Governance-Worker',daemon=False).start()
        return {'accepted':True}
    @app.post('/api/console/matrix-stop')
    async def def_matrix_stop(request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        with state['lock']:
            if state['cancel'] is not None:state['cancel'].set()
        return {'cancel_requested':True}
    @app.post('/api/console/ast')
    async def def_ast(request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        body=await request.json();source=body.get('source','')
        if not isinstance(source,str) or len(source)>MAX_AST_CHARS:raise HTTPException(status_code=400,detail='Source too long')
        return ast_advisory(source)
    @app.post('/api/console/visual-run')
    async def def_visual_run(request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        with state['lock']:
            if state['visual_running']:raise HTTPException(status_code=409,detail='Visual run already active')
            state['visual_running']=True;state['visual_report']=None;state['visual_error']=None
        url=str(request.base_url).rstrip('/')
        def def_visual_worker():
            try:
                result=def_browser_visual_audit(url,visual_root)
                with state['lock']:state['visual_report']=result
            except Exception as ex:
                with state['lock']:state['visual_error']=str(ex)
            finally:
                with state['lock']:state['visual_running']=False
        threading.Thread(target=def_visual_worker,name='VIA-Visual-Worker',daemon=False).start()
        return {'accepted':True}
    @app.get('/api/console/visual-file/{filename}')
    async def def_visual_file(filename:str,request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        if not re.fullmatch(r'(desktop|laptop|tablet|mobile)-(compact|normal|comfortable)\.png|visual-report\.json',filename):
            raise HTTPException(status_code=400,detail='Invalid file')
        path=(visual_root/filename).resolve()
        if not path.is_relative_to(visual_root.resolve()) or not path.is_file():
            raise HTTPException(status_code=404,detail='Not found')
        return FileResponse(path)
    @app.get('/api/console/governance-file/{filename}')
    async def def_governance_file(filename:str,request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        if filename not in ('output.parquet','output.csv','audit.html','report.json','manifest.json'):
            raise HTTPException(status_code=400,detail='Invalid file')
        with state['lock']:report=state['report']
        if not report or not report.get('output_directory') or state['running']:
            raise HTTPException(status_code=409,detail='Not yet complete')
        folder=Path(report['output_directory']).resolve(); root=governance_root.resolve()
        if not folder.is_relative_to(root):raise HTTPException(status_code=403,detail='Invalid run path')
        path=(folder/filename).resolve()
        if not path.is_file():raise HTTPException(status_code=404,detail='File not produced')
        return FileResponse(path,filename=filename)
    @app.get('/api/console/receipt/{filename}')
    async def def_receipt_download(filename:str,request:Request,x_via_token:str|None=Header(default=None)):
        def_authorize(request,x_via_token)
        if filename not in EMBEDDED_SOURCE_RECEIPTS:
            raise HTTPException(status_code=404,detail='Unknown source receipt')
        content=def_source_receipt(filename)
        return Response(content=content,media_type='application/octet-stream',
                headers={'Content-Disposition':'attachment; filename="'+filename+'"',
                         'X-Content-Type-Options':'nosniff'})
    return app

# ==================== 14. UPGRADE REGRESSIONS AND CLI ====================
class UnifiedEngineTests(unittest.TestCase):
    def test_module_separation(self):
        self.assertNotEqual(VERSION,MG_VERSION)
        self.assertEqual(POLICY['ssot_id'],None)
        self.assertFalse(PRODUCTION_APPROVED)
    def test_source_preservation(self):
        self.assertIn(b'VIA System Architecture',def_baseline_html())
        self.assertEqual(def_baseline_model()['version'],'v0105')
        self.assertIn(b'VIA Matrix Governance',def_source_receipt('MatrixGovernance_v0100_README.md'))
    def test_baseline_pagination(self):
        r=def_baseline_query('io',limit=2)
        self.assertEqual(len(r['rows']),2)
        self.assertGreater(r['total'],100)
        self.assertEqual(len(def_baseline_query('io',offset=2,limit=2)['rows']),2)
    def test_baseline_search(self):
        r=def_baseline_query('systems',limit=4,search='VCGC')
        self.assertGreaterEqual(r['total'],1)
    def test_mg_boundary(self):
        self.assertEqual(normalize_and_validate({'code':'2330','price':'12.3'})['amount'],'12.30')
        with self.assertRaises(ValueError):normalize_and_validate({'code':'0050','price':'1'})
    def test_mg_duplicates(self):
        prepared,rejected,duplicates=prepare_rows([{'code':'2330','price':'1'},{'ticker_id':'2330','amount':'1'}])
        self.assertEqual(len(prepared),1)
        self.assertEqual(duplicates,1)
    def test_visual_config(self):
        self.assertEqual(len(VISUAL_VIEWPORTS)*len(VISUAL_DENSITIES),12)
    def test_console_endpoints(self):
        from fastapi.testclient import TestClient
        with tempfile.TemporaryDirectory() as tmp:
            app=create_app(AuditVault(Path(tmp)))
            client=TestClient(app)
            self.assertEqual(client.get('/').status_code,200)
            self.assertEqual(client.get('/workspace/dag').status_code,200)
            self.assertEqual(client.get('/api/console/summary').status_code,403)
            token=app.state.local_token
            r=client.get('/api/console/matrix?matrix=io&limit=1',headers={'X-VIA-Token':token})
            self.assertEqual(r.status_code,200)
            self.assertEqual(len(r.json()['rows']),1)
    def test_control_matrices_are_explicit(self):
        self.assertEqual(len(CONTROL_MATRIX_TITLES),10)
        self.assertEqual(def_baseline_query('m9',limit=100)['total'],20)
        self.assertEqual(def_baseline_query('m8')['total'],0)
    def test_api_input_and_derived_matrices(self):
        from fastapi.testclient import TestClient
        with tempfile.TemporaryDirectory() as tempdir:
            app=create_app(AuditVault(Path(tempdir)))
            h={'X-VIA-Token':app.state.local_token}
            with TestClient(app) as client:
                self.assertEqual(client.get('/api/console/matrix?matrix=m10&limit=2',headers=h).status_code,200)
                response=client.post('/api/console/check-input',headers=h,
                                     json={'rows':[{'code':'2330','price':'10'}]})
                self.assertEqual(response.status_code,200)
                self.assertEqual(response.json()['status'],'PASS')
    def test_ast_rejects_bad_source(self):
        self.assertTrue(ast_advisory('eval("x")')['findings'])


def def_run_all_tests():
    suite=unittest.TestSuite([unittest.defaultTestLoader.loadTestsFromTestCase(EngineRegressionTests),
                              unittest.defaultTestLoader.loadTestsFromTestCase(UnifiedEngineTests)])
    result=unittest.TextTestRunner(verbosity=2).run(suite)
    return result.wasSuccessful()

def def_visual_smoke(data_dir:Path,port:int=0,baseline_dir:Path|None=None,with_lighthouse:bool=False):
    if FastAPI is None:raise RuntimeError('FastAPI missing')
    import uvicorn
    import socket
    with socket.socket() as sock:
        sock.bind((HOST,0));port=sock.getsockname()[1]
    vault=AuditVault(data_dir)
    app=create_app(vault)
    app.state.allowed_origins={f'http://{HOST}:{port}',f'http://localhost:{port}'}
    server=uvicorn.Server(uvicorn.Config(app,host=HOST,port=port,log_level='error',access_log=False))
    th=threading.Thread(target=server.run,name='VIA-SelfTestHTTP',daemon=True)
    th.start()
    try:
        for i in range(150):
            if server.started:break
            time.sleep(.05)
        else:raise RuntimeError('Web service not ready')
        report=def_browser_visual_audit(f'http://{HOST}:{port}',data_dir/VISUAL_OUTPUT_SUBDIR,baseline_dir)
        if with_lighthouse:
            report['lighthouse']=def_lighthouse_audit(f'http://{HOST}:{port}',data_dir/VISUAL_OUTPUT_SUBDIR)
            (data_dir/VISUAL_OUTPUT_SUBDIR/'visual-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8')
        print(json.dumps({'status':report['status'],'cases':len(report['cases']),
                          'errors':[c for c in report['cases'] if c['status']!='PASS'],
                          'output':str(data_dir/VISUAL_OUTPUT_SUBDIR)},ensure_ascii=False,indent=2)[:12000])
        return report['status'] in ('PASS','PASS_LAYOUT_ONLY')
    finally:
        server.should_exit=True
        th.join(timeout=15)

