    parser.add_argument('--visual-test',action='store_true',help='Run 12 real Chromium layout audits')
    parser.add_argument('--visual-baseline',type=Path,help='Optional trusted PNG folder to compare with screenshots')
    parser.add_argument('--lighthouse',action='store_true',help='Run locally installed Lighthouse CLI (explicit opt-in)')
    parser.add_argument('--matrix-test',action='store_true',help='Run 5-stage strict governance lifecycle')
    parser.add_argument('--agent-self-test',action='store_true',help='Agent OS local regression tests')
    parser.add_argument('--agent-report',action='store_true',help='Generate local AgentOS+VCGC evidence without server')
    parser.add_argument('--vcgc-root',type=Path,help='Read-only VCGC registry directory')
    parser.add_argument('--project-root',type=Path,help='Read-only code panorama source root')
    parser.add_argument('--doctor',action='store_true')
    parser.add_argument('--emit-ci',type=Path,help='Write optional GitHub Actions YAML locally; no push')
    parser.add_argument('--port',type=int,default=DEFAULT_PORT)
    parser.add_argument('--data-dir',type=Path,default=Path.cwd()/DATA_DIR_DEFAULT)
    parser.add_argument('--no-browser',action='store_true')
    parser.add_argument('--allow-network',action='store_true',help='Optional allowlisted HEAD probe only; requires top config enable')
    args=parser.parse_args()
    global AGENT_DEFAULT_VCGC_ROOT,AGENT_DEFAULT_SCAN_ROOT
    AGENT_DEFAULT_VCGC_ROOT=args.vcgc_root
    AGENT_DEFAULT_SCAN_ROOT=args.project_root
    if args.agent_self_test:
        result=agent_self_test()
        return 0 if result['ok'] else 1
    if args.agent_report:
        print(json.dumps(agent_matrix_report(args.data_dir/'agent_os',args.vcgc_root,args.project_root),ensure_ascii=False,indent=2))
        return 0
    if args.doctor:
        print(json.dumps({'engine':VERSION,'python':sys.version,'baseline':def_console_summary()['snapshot_version'],
            'go_live':False,'pyarrow':importlib.util.find_spec('pyarrow') is not None,
            'playwright':importlib.util.find_spec('playwright') is not None,
            'duckdb':_duckdb is not None,'polars':_pl is not None,
            'model_matrices':def_console_summary()['matrices'],
            'network_enabled':False},ensure_ascii=False,indent=2));return 0
    if args.emit_ci:
        print(def_emit_ci(args.emit_ci));return 0
    if args.self_test:return 0 if def_run_all_tests() else 1
    if args.smoke:return 0 if smoke_run(args.data_dir) else 1
    if args.visual_test:return 0 if def_visual_smoke(args.data_dir,baseline_dir=args.visual_baseline,with_lighthouse=args.lighthouse) else 2
    if args.matrix_test:
        rep=run_pipeline(SAMPLE_ROWS,args.data_dir/GOVERNANCE_OUTPUT_SUBDIR)
        print(json.dumps({'status':rep['status'],'gate':rep['gate'],'cases':len(rep['cases']),
                          'output':rep.get('output_directory')},ensure_ascii=False,indent=2))
        return 0 if rep['gate']['local_reference_pass'] else 1
    if FastAPI is None:parser.error('pip install fastapi uvicorn')
    if not 0<=args.port<=65535 or (args.port and args.port<1024):
        parser.error('port must be 0 (auto) or between 1024 and 65535')
    import socket
    if AUTO_PORT_FALLBACK:
        with socket.socket() as listener:
            try:
                listener.bind((HOST,args.port))
                args.port=listener.getsockname()[1]
            except OSError:
                listener.bind((HOST,0))
                args.port=listener.getsockname()[1]
    network_allowed=args.allow_network and OPTIONAL_NETWORK
    app=create_app(AuditVault(args.data_dir),network_allowed=network_allowed)
    app.state.allowed_origins={f'http://{HOST}:{args.port}',f'http://localhost:{args.port}'}
    url=f'http://{HOST}:{args.port}'
    print(f'理 · VIA System Integration Engine v{VERSION}\n{url}\nData: {args.data_dir.resolve()}\nProduction: BLOCKED (pending native integrations)')
    if not args.no_browser:threading.Timer(0.8,lambda:webbrowser.open(url)).start()
    uvicorn.run(app,host=HOST,port=args.port,log_level='warning',workers=1)
    return 0

