def agent_enhance_console():
    """Maintain exact prior UI layout and append three coherent sections."""
    global CONSOLE_HTML
    if 'data-page="agents"' in CONSOLE_HTML:return
    CONSOLE_HTML=CONSOLE_HTML.replace('VIA · VCGC · SYSTEM INTEGRATION · ENGINE v__UI_VERSION__',
                                      'VIA · AGENT OS · VCGC · SYSTEM INTEGRATION · ENGINE v__UI_VERSION__',1)
    CONSOLE_HTML=CONSOLE_HTML.replace('</style>','</style>'+AGENT_UI_ADDON,1) if '</style>' in CONSOLE_HTML else CONSOLE_HTML
    CONSOLE_HTML=CONSOLE_HTML.replace('</nav>',AGENT_UI_NAV+'</nav>',1)
    CONSOLE_HTML=CONSOLE_HTML.replace('</main>',AGENT_UI_PAGES+'</main>',1)
    old="'archive','technical'];"
    if old not in CONSOLE_HTML:raise RuntimeError('Console page registry anchor not found')
    CONSOLE_HTML=CONSOLE_HTML.replace(old,"'archive','technical','agents','vcgc','panorama'];",1)
    if '</script>' not in CONSOLE_HTML:raise RuntimeError('Console script anchor missing')
