_BASE_APP_WITH_CONSOLE=create_app

def create_app(vault:AuditVault,network_allowed:bool=False):
    """Extend existing System Integration FastAPI app without altering legacy endpoints."""
    app=_BASE_APP_WITH_CONSOLE(vault,network_allowed)
    from fastapi import Header as _Header
    token=app.state.local_token
    memory_file=vault.root/'agent_os'/'agent_memory.sqlite3'
    def authorize(request,provided):
        if not provided or not secrets.compare_digest(provided,token):
            raise HTTPException(status_code=403,detail='Invalid local session token')
        origin=request.headers.get('origin')
        if origin and origin not in app.state.allowed_origins:
            raise HTTPException(status_code=403,detail='Cross-origin request denied')
    @app.get('/api/agent/catalog')
    async def agent_catalog(request:Request,x_via_token:str|None=Header(default=None)):
        authorize(request,x_via_token);return agent_skill_catalog()
    @app.post('/api/agent/plan')
    async def agent_plan_route(request:Request,x_via_token:str|None=Header(default=None)):
        authorize(request,x_via_token)
        body=await request.json()
        try:return agent_plan(body.get('objective'),body.get('task_type','integration'),body.get('constraints'))
        except (ValueError,TypeError) as error:raise HTTPException(status_code=400,detail=str(error)) from error
    @app.post('/api/agent/run-local')
    async def agent_local_route(request:Request,x_via_token:str|None=Header(default=None)):
        authorize(request,x_via_token)
        body=await request.json()
        try:return await asyncio.to_thread(agent_run_local,body.get('objective'),body.get('task_type','integration'),AGENT_DEFAULT_VCGC_ROOT,AGENT_DEFAULT_SCAN_ROOT)
        except (TypeError,ValueError) as error:raise HTTPException(status_code=400,detail=str(error)) from error
    @app.get('/api/agent/vcgc')
    async def agent_registry_route(request:Request,x_via_token:str|None=Header(default=None)):
        authorize(request,x_via_token)
        return await asyncio.to_thread(agent_vcgc_inspect,AGENT_DEFAULT_VCGC_ROOT)
    @app.get('/api/agent/panorama')
    async def agent_scan_route(request:Request,x_via_token:str|None=Header(default=None)):
        authorize(request,x_via_token)
        return await asyncio.to_thread(agent_panorama_scan,AGENT_DEFAULT_SCAN_ROOT)
    @app.get('/api/agent/memory')
    async def agent_memory_route(request:Request,category:str|None=None,q:str='',x_via_token:str|None=Header(default=None)):
        authorize(request,x_via_token)
        try:return await asyncio.to_thread(agent_memory_search,memory_file,category,q)
        except (ValueError,TypeError) as error:raise HTTPException(status_code=400,detail=str(error)) from error
    @app.post('/api/agent/memory')
    async def agent_memory_write_route(request:Request,x_via_token:str|None=Header(default=None)):
        authorize(request,x_via_token)
        body=await request.json()
        try:return await asyncio.to_thread(agent_memory_append,memory_file,body.get('category'),body.get('content'),body.get('explicit_approval',False))
        except (ValueError,TypeError,PermissionError) as error:raise HTTPException(status_code=400,detail=str(error)) from error
    @app.post('/api/agent/evidence')
    async def agent_report_route(request:Request,x_via_token:str|None=Header(default=None)):
        authorize(request,x_via_token)
        return await asyncio.to_thread(agent_matrix_report,vault.root/'agent_os',AGENT_DEFAULT_VCGC_ROOT,AGENT_DEFAULT_SCAN_ROOT)
    return app


def agent_self_test():
    """Real local tests; exceptions fail, and external integrations remain untested."""
    import unittest as _ut
    class AgentTests(_ut.TestCase):
        def test_skill_contracts(self):
            self.assertEqual(len(AGENT_SKILLS),8)
            self.assertEqual(len(AGENT_MEMORY_SCHEMAS),6)
            self.assertTrue(all(k in AGENT_SKILLS for val in AGENT_SKILLS.values() for k in val['depends_on']))
        def test_plan_dependency(self):
            for typ in ('integration','code','research','investment'):
                plan=agent_plan('review this project',typ)
                index={n:i for i,n in enumerate(plan['order'])}
                self.assertTrue(all(index[x['source']]<index[x['target']] for x in plan['edges']))
                self.assertEqual(plan['order'][-1],'via-memory-manager')
                self.assertFalse(plan['production_approved'])
        def test_plan_fails_closed(self):
            with self.assertRaises(ValueError):agent_plan('')
            with self.assertRaises(ValueError):agent_plan('x','unknown')
        def test_memory_append_dedupe_verify(self):
            with tempfile.TemporaryDirectory() as d:
                db=Path(d)/'agent.sqlite3';data={'decision':'use DAG','rationale':'dependencies'}
                with self.assertRaises(PermissionError):agent_memory_append(db,'architecture_memory',data)
                item=agent_memory_append(db,'architecture_memory',data,True)
                self.assertEqual(item['status'],'APPENDED')
                self.assertEqual(agent_memory_append(db,'architecture_memory',data,True)['status'],'DUPLICATE')
                self.assertEqual(agent_memory_verify(db)['status'],'PASS')
                self.assertEqual(agent_memory_search(db,keyword='DAG')['total_returned'],1)
        def test_memory_reject_sensitive(self):
            with tempfile.TemporaryDirectory() as d:
                with self.assertRaises(ValueError):agent_memory_append(Path(d)/'db','architecture_memory',{'decision':'Bearer abcd'},True)
        def test_operating_memory_fails_closed(self):
            with tempfile.TemporaryDirectory() as d:
                with self.assertRaises(PermissionError):agent_memory_append(Path(d)/'db','operating_memory',{'routing_rule':'anything'},True)
        def test_vcgc_collision(self):
            with tempfile.TemporaryDirectory() as d:
                a={'records':[{'system':'VDF','name':'Price','ssot_id':'SSOT-01','synonyms':{'px':'price'}},
                              {'system':'VRN','name':'Amount','ssot_id':'SSOT-01','synonyms':{'px':'amount'}},
                              {'system':'VRN','name':'Missing','ssot_id':'','regex':{'wrong':'('}}]}
                (Path(d)/'registry.json').write_text(json.dumps(a),encoding='utf-8')
                result=agent_vcgc_inspect(d)
                self.assertEqual(result['status'],'CONFLICT')
                self.assertEqual(len(result['pending_approval']),1)
                self.assertGreaterEqual(len(result['conflicts']),3)
                self.assertEqual(result['writes'],0)
        def test_panorama_python_import(self):
            with tempfile.TemporaryDirectory() as d:
                a=Path(d);(a/'pkg').mkdir()
                (a/'pkg'/'__init__.py').write_text('',encoding='utf-8')
                (a/'pkg'/'x.py').write_text('def run(): return 2\n',encoding='utf-8')
                (a/'pkg'/'y.py').write_text('from . import x\ndef use():return x.run()\n',encoding='utf-8')
                (a/'wrong.py').write_text('def x(:\n',encoding='utf-8')
                (a/'page.html').write_text('<div id="duplicate"></div><b id="duplicate"></b>',encoding='utf-8')
                scanned=agent_panorama_scan(a)
                self.assertTrue(any(x['type']=='PYTHON_SYNTAX' for x in scanned['findings']))
                self.assertTrue(any(x['type']=='DUPLICATE_DOM_ID' for x in scanned['findings']))
                self.assertGreaterEqual(scanned['summary']['files_scanned'],4)
                self.assertTrue(any(e['source'].endswith('x.py') and e['target'].endswith('y.py') for e in scanned['edges']))
        def test_local_execution_claims(self):
            with tempfile.TemporaryDirectory() as d:
                result=agent_run_local('test scope','integration',None,Path(d))
                self.assertGreaterEqual(result['local_pass_count'],2)
                self.assertEqual(result['external_ai_calls'],0)
                self.assertEqual(result['production_gate'],'BLOCKED')
        def test_three_pass(self):
            with tempfile.TemporaryDirectory() as d:
                view=agent_panorama_three_pass(Path(d))
                self.assertEqual(len(view['three_pass_review']),3)
                self.assertEqual(view['three_pass_review'][-1]['status'],'PENDING_ACTUAL_PATCH')
        def test_report_is_nonproduction(self):
            with tempfile.TemporaryDirectory() as d:
                result=agent_matrix_report(d)
                self.assertFalse(result['go_live'])
                self.assertTrue(Path(result['report_path']).is_file())
                self.assertTrue(Path(result['html_path']).is_file())
        def test_ui_injected(self):
            self.assertIn('data-page="agents"',CONSOLE_HTML)
            self.assertIn('id="memory-consent"',CONSOLE_HTML)
            self.assertIn("'panorama'];",CONSOLE_HTML)
    suite=_ut.defaultTestLoader.loadTestsFromTestCase(AgentTests)
    stream=io.StringIO()
    report=_ut.TextTestRunner(stream=stream,verbosity=2).run(suite)
    print(stream.getvalue())
    return {'ok':report.wasSuccessful(),'passed':report.testsRun-len(report.failures)-len(report.errors),
            'tests':report.testsRun,'failures':len(report.failures),'errors':len(report.errors),
            'scope':'Local Agent OS contracts, memory, VCGC conflict scan and source scanners only'}

